(function(root){
function createReportPDF(jsPDF,state,result){
 const doc=new jsPDF({unit:'mm',format:'a4',compress:true}),ink='#243c36',green='#315b48',palette=['#c5d4af','#e9d5ae','#b9cfcb','#d8c6bc','#c9c8dc','#dfcba0'];
 const number=n=>Number(n.toFixed(2)).toString(),text=(value,x,y,size=10)=>{doc.setTextColor(ink);doc.setFontSize(size);doc.text(String(value),x,y);};
 function title(label){text('SHEETWISE / CUTTING REPORT',14,16,9);text(label,14,25,15);}
 function table(rows,headers,y,widths){const xs=[14];for(let i=0;i<widths.length;i++)xs.push(xs[i]+widths[i]);const heading=()=>{doc.setFillColor('#edf3e5');doc.rect(14,y,182,8,'F');headers.forEach((v,i)=>text(v,xs[i]+2,y+5.5,8));y+=8;};heading();for(const row of rows){doc.setFontSize(8);const cells=row.map((value,i)=>doc.splitTextToSize(String(value),widths[i]-4)),height=Math.max(8,...cells.map(lines=>lines.length*3.7+3));if(y+height>277){doc.addPage();title('Cutting list continued');y=34;heading();}cells.forEach((value,i)=>text(value,xs[i]+2,y+5,8));doc.setDrawColor('#d9dfd7');doc.line(14,y+height,196,y+height);y+=height;}return y;}
 result.sheets.forEach((sheet,index)=>{if(index)doc.addPage();title('Sheet '+(index+1)+' / '+result.sheets.length+' - '+sheet.label);let y=32;
 if(index===0){const band=state.parts.reduce((sum,p)=>{const e=p.edges||{};return sum+((e.top?p.w:0)+(e.bottom?p.w:0)+(e.left?p.h:0)+(e.right?p.h:0))*p.qty;},0)/100;const utilization=result.area?100*result.used/result.area:0;const cards=[['Utilization',utilization.toFixed(1)+'%'],['Sheets',String(result.sheets.length)],['Unused area',(100-utilization).toFixed(1)+'%'],['Edge banding',band.toFixed(2)+' m']];cards.forEach(([label,value],i)=>{const x=14+i*46;doc.setFillColor('#f1f5eb');doc.roundedRect(x,y,44,17,2,2,'F');text(label,x+3,y+5,8);text(value,x+3,y+12,12);});y+=24;}
 text(number(sheet.w)+' x '+number(sheet.h)+' cm  |  Kerf '+number(state.kerf*10)+' mm  |  '+sheet.pieces.length+' pieces',14,y,9);y+=8;
 const scale=Math.min(182/sheet.w,98/sheet.h),left=14+(182-sheet.w*scale)/2,top=y;doc.setFillColor('#e8eadf');doc.setDrawColor('#a8b29b');doc.rect(left,top,sheet.w*scale,sheet.h*scale,'FD');
 const groups=new Map();sheet.pieces.forEach(p=>{const key=JSON.stringify([p.label,p.w,p.h]);if(!groups.has(key))groups.set(key,{...p,count:0,ref:groups.size+1});groups.get(key).count++;});
 for(const p of sheet.pieces){const x=left+p.x*scale,yy=top+p.y*scale,w=p.w*scale,h=p.h*scale;doc.setFillColor(palette[p.color%palette.length]||palette[0]);doc.setDrawColor('#ffffff');doc.setLineWidth(.2);doc.rect(x,yy,w,h,'FD');const entry=groups.get(JSON.stringify([p.label,p.w,p.h]));if(w>8&&h>6){doc.setFontSize(7);doc.setTextColor(ink);doc.text('#'+entry.ref,x+w/2,yy+h/2,{align:'center'});}const e=p.edges||{},edges=p.turn?{top:e.left,right:e.top,bottom:e.right,left:e.bottom}:e;doc.setDrawColor(green);doc.setLineWidth(.5);if(edges.top)doc.line(x,yy,x+w,yy);if(edges.bottom)doc.line(x,yy+h,x+w,yy+h);if(edges.left)doc.line(x,yy,x,yy+h);if(edges.right)doc.line(x+w,yy,x+w,yy+h);}
 y+=sheet.h*scale+8;text('Parts to cut - sizes match the orientation above',14,y,10);y+=4;table([...groups.values()].map(p=>['#'+p.ref,p.label,number(p.w),number(p.h),p.count]),['Ref','Part','Width (cm)','Height (cm)','Qty'],y,[14,80,32,32,24]);
 });
 if(result.unplaced.length){doc.addPage();title('Unplaced parts');text('These parts are not included in the cutting layouts.',14,34,10);const groups=new Map();result.unplaced.forEach(p=>{const key=p.groupId??p.label;if(!groups.has(key))groups.set(key,{...p,count:0});groups.get(key).count++;});table([...groups.values()].map(p=>[p.label,number(p.w),number(p.h),p.count]),['Part','Width (cm)','Height (cm)','Qty'],40,[94,32,32,24]);}
 const count=doc.getNumberOfPages();for(let i=1;i<=count;i++){doc.setPage(i);doc.setFontSize(8);doc.setTextColor('#64705d');doc.text('Sheetwise | Verify dimensions before cutting.',14,288);doc.text(i+' / '+count,196,288,{align:'right'});}doc.setProperties({title:'Sheetwise cutting report',subject:'Workshop cutting layouts',creator:'Sheetwise'});return doc;
}
if(typeof module!=='undefined')module.exports={createReportPDF};else root.ReportPDF={createReportPDF};
})(typeof window!=='undefined'?window:this);
